const p = msg.payload;
if (!p || typeof p !== 'object') {
    node.error('Payload MQTT não é um objeto JSON', msg);
    return null;
}

const deviceId = String(p.device_id || '').trim();
const temp = Number(p.temp);
const humidity = Number(p.umid);
const heatIndex = p.ic === undefined || p.ic === null ? null : Number(p.ic);
const rssi = p.rssi === undefined || p.rssi === null ? null : Number(p.rssi);

if (!/^[a-zA-Z0-9_-]{1,64}$/.test(deviceId)) {
    node.error('device_id ausente ou inválido', msg);
    return null;
}
if (!Number.isFinite(temp) || temp < -40 || temp > 80) {
    node.error('temperatura fora da faixa válida', msg);
    return null;
}
if (!Number.isFinite(humidity) || humidity < 0 || humidity > 100) {
    node.error('umidade fora da faixa válida', msg);
    return null;
}
if (heatIndex !== null && !Number.isFinite(heatIndex)) {
    node.error('índice de calor inválido', msg);
    return null;
}
if (rssi !== null && (!Number.isFinite(rssi) || rssi < -120 || rssi > 0)) {
    node.error('RSSI fora da faixa válida', msg);
    return null;
}

const escapeTag = (value) => String(value).replace(/([ ,=\\])/g, '\\$1');
const sensor = escapeTag(p.sensor || 'legacy');
const fields = [`temperatura=${temp}`, `umidade=${humidity}`];
if (heatIndex !== null) fields.push(`indice_calor=${heatIndex}`);
if (rssi !== null) fields.push(`rssi=${rssi}`);

msg.payload = `ambiente,device_id=${escapeTag(deviceId)},sensor=${sensor} ${fields.join(',')}`;
msg.method = 'POST';
msg.url = `${env.get('INFLUXDB_URL')}/api/v2/write?org=${encodeURIComponent(env.get('INFLUXDB_ORG'))}&bucket=${encodeURIComponent(env.get('INFLUXDB_BUCKET'))}&precision=ns`;
msg.headers = {
    'Authorization': `Token ${env.get('INFLUXDB_TOKEN')}`,
    'Content-Type': 'text/plain; charset=utf-8'
};
return msg;

if (msg.statusCode !== 204) {
    node.error(`InfluxDB respondeu HTTP ${msg.statusCode}: ${msg.payload}`, msg);
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: 'medição gravada' });
return null;
